def find_mate_in_n(board, depth, max_depth=3, path=None):
    """Recursively search for mate in n moves."""
    if path is None:
        path = []

    if board.is_checkmate():
        return True, path, 0

    if depth == 0:
        return False, [], None

    legal_moves = list(board.legal_moves)

    if not board.turn:  # White's turn (minimizing)
        # White tries to avoid mate
        for move in legal_moves:
            board.push(move)
            mate_found, variation, mate_in = find_mate_in_n(board, depth-1, max_depth, path + [move])
            board.pop()

            if not mate_found:
                # White found a way to avoid mate
                return False, [], None

        # All White moves lead to mate
        if legal_moves:
            move = legal_moves[0]
            board.push(move)
            mate_found, variation, mate_in = find_mate_in_n(board, depth-1, max_depth, path + [move])
            board.pop()
            return True, [move] + variation, (mate_in + 1 if mate_in is not None else 1)
        else:
            return True, [], 0

    else:  # Black's turn (maximizing, trying to mate)
        best_variation = None
        best_mate_in = None

        for move in legal_moves:
            board.push(move)
            mate_found, variation, mate_in = find_mate_in_n(board, depth-1, max_depth, path + [move])
            board.pop()

            if mate_found:
                if best_mate_in is None or mate_in < best_mate_in:
                    best_mate_in = mate_in
                    best_variation = [move] + variation

        if best_variation is not None:
            return True, best_variation, (best_mate_in + 1 if best_mate_in is not None else 1)

        return False, [], None

