import sys
import platform

# First install the stockfish Python wrapper
subprocess.check_call([sys.executable, "-m", "pip", "install", "stockfish"])

# Now install stockfish engine based on platform
if platform.system() == "Windows":
    # For Windows, we might need a different approach
    print("Windows detected - trying to find stockfish...")
    # Try to use stockfish-py package which includes binary
    try:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "stockfish-py"])
    except:
        print("Could not install stockfish-py")
else:
    # For Linux/Mac, try to install via package manager or download
    print(f"{platform.system()} detected - trying to install stockfish...")
    try:
        # Try to install via apt-get for Linux
        if platform.system() == "Linux":
            subprocess.run(["sudo", "apt-get", "install", "stockfish"], check=False)
        # For macOS, could use brew, but we'll handle that separately
    except:
        print("Could not install stockfish via system package manager")

# Now try to import and use stockfish
try:
    from stockfish import Stockfish

    # First, let's see what stockfish module gives us
    print("Successfully imported stockfish module")

    # Try to create stockfish with default path
    try:
        sf = Stockfish()
        print("Created Stockfish instance with default path")
    except Exception as e:
        print(f"Error creating Stockfish with default path: {e}")
        # Try to find stockfish in PATH
        import shutil
        stockfish_path = shutil.which("stockfish")
        if stockfish_path:
            print(f"Found stockfish at: {stockfish_path}")
            sf = Stockfish(path=stockfish_path)
        else:
            print("Stockfish binary not found in PATH")
            # Try common locations
            import os
            common_paths = [
                "/usr/bin/stockfish",
                "/usr/local/bin/stockfish",
                "/opt/homebrew/bin/stockfish",
                "C:\\Program Files\\Stockfish\\stockfish.exe"
            ]
            for path in common_paths:
                if os.path.exists(path):
                    print(f"Found stockfish at: {path}")
                    sf = Stockfish(path=path)
                    break
            else:
                print("Could not find stockfish binary")
except Exception as e:
    print(f"Import error: {e}")", "session_id": 1774501682}

