{"task": "Write a quick Python script to check if any move leads to forced mate in 3 moves for black.

import chess

def has_forced_mate(board, depth):
    if board.is_checkmate():
        return True
    if depth == 0:
        return False
    # black to move
    for move in board.legal_moves:
        board.push(move)
        # white's turn: if all white moves lead to forced mate for black
        mate_for_all = True
        for wmove in board.legal_moves:
            board.push(wmove)
            if not has_forced_mate(board, depth-1):
                mate_for_all = False
                board.pop()
                break
            board.pop()
        board.pop()
        if mate_for_all:
            return True
    return False

board = chess.Board("k3r3/ppp3pp/p7/Q7/3n4/P2RBBqP/PP6/K7 b - - 0 1")
for move in board.legal_moves:
    board.push(move)
    if board.is_checkmate():
        print(f"Mate in 1: {move}")
    else:
        # check if black can force mate in 2 more moves (depth 2)
        mate_found = True
        for wmove in board.legal_moves:
            board.push(wmove)
            # black's turn again, check if any move leads to mate in 1
            mate_in_one = False
            for bmove in board.legal_moves:
                board.push(bmove)
                if board.is_checkmate():
                    mate_in_one = True
                    board.pop()
                    break
                board.pop()
            board.pop()
            if not mate_in_one:
                mate_found = False
                break
        if mate_found:
            print(f"Mate in 2: {move}")
    board.pop()
print("Done")"}

